func TestDecoderValidStdinProducesJSON(t *testing.T) {
	cmd := exec.Command("go", "run", ".")
	cmd.Stdin = strings.NewReader("answer = 42\n")
	out, err := cmd.Output()
	if err != nil {
		t.Fatalf("decoder failed: %v", err)
